<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script nonce="<?=e(csp_nonce())?>">const base={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{font:{size:8}}},y:{ticks:{font:{size:8}}}}};function chart(id,type,labels,data,goal=null,goalLabel='Goal'){const ds=[{label:'Actual',data,borderWidth:1.5,pointRadius:type==='line'?1.5:0,fill:type==='line'?false:true,backgroundColor:'rgba(239,107,79,.65)',borderColor:'#ec6a4f',tension:.25}];if(goal>0)ds.push({label:goalLabel,data:labels.map(()=>goal),borderWidth:1.5,borderDash:[5,4],pointRadius:0,fill:false,borderColor:'#64748b'});new Chart(document.getElementById(id),{type,data:{labels,datasets:ds},options:{...base,plugins:{...base.plugins,legend:{display:goal>0,position:'top'}}}})}chart('equityChart','line',<?=json_encode($equityLabels)?>,<?=json_encode($equityData)?>);chart('balanceChart','line',<?=json_encode($balanceLabels)?>,<?=json_encode($balanceData)?>);chart('rChart','bar',<?=json_encode($rLabels)?>,<?=json_encode($rData)?>);chart('systemChart','bar',<?=json_encode($systemLabels)?>,<?=json_encode($systemData)?>);chart('monthChart','bar',<?=json_encode($monthLabels)?>,<?=json_encode($monthData)?>,<?=$monthlyGoal?>,'Monthly goal');chart('yearChart','bar',<?=json_encode(array_map(fn($m)=>date('M',strtotime($m.'-01')),array_keys($year)))?>,<?=json_encode(array_values($year))?>,<?=$yearlyGoal?>,'Yearly goal');</script>
